#!POPCORN leaderboard matmul_v2
# matmul_v2 timing diagnostic
#
# Generated by contests/gpu-mode/06-matmul-v2/package_matmul.py from Crisp source.  The kernels are Crisp,
# compiled to PTX by crisp-compile; this file only loads that PTX with the CUDA driver API and launches it.
#
# Crisp source:
# -------------------------------------------------------------------------
# --- matmul_b200_tcgen05.crisp ---
# ;; matmul_v2 on the B200 (sm_100a) -- tcgen05, accumulator in tensor memory.
# ;;
# ;; The benchmark suite's section-2 fp16 kernel (scripts/crisp_bench/gen_b200.py, endeavour 209), with C
# ;; in fp16: the epilogue rounds as each element leaves tensor memory (store-tile (to-half D) ...).
# ;; Warp-specialized :epilogue 4 / :producer 1 / :mma 1, a 2-deep TMA ring of A and B^T tiles (128-byte
# ;; swizzle), one 128 x 256 output tile per workgroup (the tile grid; 2 workgroups per SM).
# ;;
# ;; tcgen05 reads B only K-major, so B is the contest's b TRANSPOSED: (N K) contiguous, i.e. (K N) col-major.
# ;; Requires M % 128 = 0, N % 256 = 0, K % 64 = 0.
#
# (def-type a-mat (matrix half :address-space :global :align :compact :contiguous-term :row-major))
# (def-type b-mat (matrix half :address-space :global :align :compact :contiguous-term :col-major))
# (def-type c-mat (matrix half :address-space :global :align :compact :contiguous-term :row-major))
#
# (def-kernel matmul (A B &out C)
#   (declare #'(a-mat b-mat &out c-mat)
#            (global-size :derive-from C :strategy :strided)
#            (local-size :set-to 192))                 ; epilogue warpgroup + producer warp + mma warp
#   (let ((A-ring    (make-scratch-matrix-ring half (128 64) :ring-count 2))
#         (B-ring    (make-scratch-matrix-ring half (256 64) :ring-count 2))   ; B^T: N x K
#         (D         (make-tcgen05-accumulator float (128 256) 0.0))
#         (K         (inner-dimension A B))
#         (empty     (make-async-barrier-ring :ring-count 2 :mode :block :arrivals 1 :initial-state :signaled))
#         (full      (make-async-barrier-ring :ring-count 2 :mode :block :arrivals 2 :initial-state :waiting))
#         (acc-full  (make-async-barrier-ring :ring-count 1 :mode :block :arrivals 1 :initial-state :waiting))
#         (acc-empty (make-async-barrier-ring :ring-count 1 :mode :block :arrivals 4 :initial-state :signaled)))
#     (tile-stride C (128 256) (grid-y grid-x)
#       (with-warp-specialization (:epilogue 4 :producer 1 :mma 1)
#           (:epilogue
#             (await (ring-get acc-full 0))
#             (store-tile (to-half D) C (grid-y grid-x))
#             (signal (ring-get acc-empty 0)))
#           (:producer
#             (dotimes (grid-k (/ (to-ulong K) (to-ulong 64)))
#               (let ((slot (mod grid-k (to-ulong 2))))
#                 (await (ring-get empty slot))
#                 (load-tile A (ring-get A-ring slot) (grid-y grid-k) :barrier (ring-get full slot) :swizzle :128b)
#                 (load-tile B (ring-get B-ring slot) (grid-x grid-k) :barrier (ring-get full slot) :swizzle :128b))))
#           (:mma
#             (await (ring-get acc-empty 0))
#             (set! D (make-tcgen05-accumulator float (128 256) 0.0))
#             (dotimes (grid-k (/ (to-ulong K) (to-ulong 64)))
#               (let ((slot (mod grid-k (to-ulong 2))))
#                 (await (ring-get full slot))
#                 (tcgen05-accumulate-via-tile (128 256 64) D (ring-get A-ring slot) (ring-get B-ring slot)
#                                              :swizzle :128b :on-complete (ring-get empty slot))))
#             (tcgen05-commit (ring-get acc-full 0)))))))
#
# --- transpose_b.crisp ---
# ;; matmul_v2 -- B (K N) -> BT (N K), for the H100 wgmma kernel, which reads B K-major.
# ;;
# ;; torch's `b.t()` copy took 160 us of a 462 us call at 4096x5120 (a strided element copy).  This is
# ;; the textbook tiled transpose: 256 threads move a 64x64 tile.  Consecutive threads walk a ROW of B on
# ;; the way in and a row of BT on the way out, so both global sides are coalesced; the tile is padded to
# ;; 65 columns so the column-wise shared-memory writes do not all land in one bank.
# ;; Shapes must be multiples of 64 (the dispatch guarantees it).
# (def-type h-mat (matrix half :address-space :global :align :compact :contiguous-term :row-major))
#
# (def-kernel transpose_b (B &out BT)
#   (declare #'(h-mat &out h-mat) (local-size :set-to 256))
#   (let ((tile (make-scratch-matrix half (64 65))))
#     (tile-stride BT (64 64) (gy gx)
#       (let ((n0 (* gy 64ul))
#             (k0 (* gx 64ul))
#             (c  (rem (get-local-id 0) 64ul))
#             (r0 (/ (get-local-id 0) 64ul)))
#         (dotimes (s 16)
#           (let ((r (+ r0 (* (to-ulong s) 4ul))))
#             (set! (~ tile c r) (~ B (+ k0 r) (+ n0 c)))))
#         (sync-workgroup)
#         (dotimes (s 16)
#           (let ((r (+ r0 (* (to-ulong s) 4ul))))
#             (set! (~ BT (+ n0 r) (+ k0 c)) (~ tile r c))))
#         (sync-workgroup)))))
# -------------------------------------------------------------------------

